/*
 * A042464  Numerators of continued fraction convergents to sqrt(760).
 * https://oeis.org/A042464
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = p_n, where p_n are the numerators of the convergents of
 *            the continued fraction of √760. The recurrence is p_n = a_n ·
 *            p_{n-1} + p_{n-2} with the partial quotients a_n generated by
 *            the standard square‑root continued‑fraction algorithm
 * Range:     u8 none, u16 n <= 9, u32 n <= 18, u64 n <= 36, u128 n <= 75,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>

/* Compute the sequence term a(n). */
seq_t a(idx_t n)
{
    const seq_t D = (seq_t)760;

    /* Compute a0 = ⌊√D⌋ without using floating point. */
    seq_t a0 = 0;
    while ((a0 + 1) * (a0 + 1) <= D) {
        ++a0;
    }

    /* Continued‑fraction state variables. */
    seq_t m = 0;
    seq_t d = 1;
    seq_t a_quot = a0;          /* a_0 */

    /* Convergent recurrence: p_{-2} = 0, p_{-1} = 1. */
    seq_t p_nm2 = 0;   /* p_{-2} */
    seq_t p_nm1 = 1;   /* p_{-1} */
    seq_t p_i   = 0;   /* p_n */

    for (idx_t i = 0; i <= n; ++i) {
        /* Compute current convergent numerator. */
        p_i = a_quot * p_nm1 + p_nm2;

        /* Shift for next iteration. */
        p_nm2 = p_nm1;
        p_nm1 = p_i;

        if (i == n) break;   /* the required term has been found */

        /* Generate next partial quotient a_{i+1}. */
        seq_t m_next = d * a_quot - m;
        seq_t d_next = (D - m_next * m_next) / d;
        seq_t a_next = (a0 + m_next) / d_next;

        m = m_next;
        d = d_next;
        a_quot = a_next;
    }

    return p_i;
}
